# WAR INTEL — collector wiring (backend). Frontend is the separate index.html.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-intel-collector.ps1
$ErrorActionPreference = 'Stop'
Write-Host 'Installing WAR INTEL collector wiring...' -ForegroundColor Cyan
if (-not (Test-Path 'src\api')) { New-Item -ItemType Directory -Force -Path 'src\api' | Out-Null }
if (-not (Test-Path 'src\deploy')) { New-Item -ItemType Directory -Force -Path 'src\deploy' | Out-Null }

# ---- src/api/wiredApp.ts ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\api\wiredApp.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/api/wiredApp.ts' -ForegroundColor Green

# ---- src/deploy/server.ts ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\deploy\server.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/deploy/server.ts' -ForegroundColor Green

Write-Host 'Also replace miniapp/index.html with the exported file (WAR INTEL UI).' -ForegroundColor Yellow
Write-Host 'Remember: re-apply BOT_USERNAME=G_WarArenaBot if needed.' -ForegroundColor Yellow